package fizeau

import (
	"strings"
	"time"

	"github.com/DocumentDrivenDX/fizeau/internal/routehealth"
	"github.com/DocumentDrivenDX/fizeau/internal/routing"
)

const stickyRouteLeaseTTL = routehealth.DefaultLeaseTTL

func (s *service) routeLeaseStore() *routehealth.LeaseStore {
	if s.routeLeases == nil {
		s.routeLeases = routehealth.NewLeaseStore()
	}
	return s.routeLeases
}

func (s *service) routeUtilizationStore() *routehealth.UtilizationStore {
	if s.routeUtilization == nil {
		s.routeUtilization = routehealth.NewUtilizationStore()
	}
	return s.routeUtilization
}

func (s *service) applyStickyRouteLease(stickyKey string, decision *RouteDecision) {
	if s == nil || decision == nil || strings.TrimSpace(stickyKey) == "" {
		return
	}
	decision.Sticky.KeyPresent = true
	if decision.Harness != "fiz" || decision.Provider == "" {
		decision.Sticky.Assignment = "not_applicable"
		return
	}

	now := time.Now().UTC()
	store := s.routeLeaseStore()
	baseProvider, _, _ := splitEndpointProviderRef(decision.Provider)
	if baseProvider == "" {
		baseProvider = decision.Provider
	}
	if baseProvider == "" || decision.Model == "" {
		return
	}

	key := routehealth.NormalizeLeaseKey(stickyKey, baseProvider, decision.Model)
	if lease, ok := store.Live(now, key); ok {
		if candidate, found := stickyLeaseCandidate(decision.Candidates, decision.Harness, baseProvider, decision.Model, lease.Endpoint); found && candidate.Eligible {
			store.Acquire(now, stickyRouteLeaseTTL, key, baseProvider, lease.Endpoint, decision.Model)
			decision.Provider = candidate.Provider
			decision.Endpoint = candidate.Endpoint
			decision.ServerInstance = candidate.ServerInstance
			decision.Sticky.Assignment = "reused"
			decision.Sticky.ServerInstance = candidate.ServerInstance
			decision.Sticky.Reason = "live sticky lease reused"
			return
		}
		reason := "endpoint disappeared"
		if candidate, found := stickyLeaseCandidate(decision.Candidates, decision.Harness, baseProvider, decision.Model, lease.Endpoint); found {
			reason = candidate.Reason
			if reason == "" {
				reason = "sticky endpoint became ineligible"
			}
		} else if candidate, found := stickyLeaseAnyEndpoint(decision.Candidates, decision.Harness, baseProvider, lease.Endpoint); found {
			reason = candidate.Reason
			if reason == "" {
				reason = "sticky endpoint became ineligible"
			}
		}
		store.Invalidate(now, key, reason)
	}
	if decision.Provider == "" && decision.Endpoint == "" {
		decision.Sticky.Assignment = "none"
		return
	}
	chosenEndpoint := decision.ServerInstance
	if chosenEndpoint == "" {
		chosenEndpoint = decision.Endpoint
	}
	if chosenEndpoint == "" {
		_, chosenEndpoint, _ = splitEndpointProviderRef(decision.Provider)
	}
	if chosenEndpoint == "" {
		chosenEndpoint = decision.Provider
	}
	if chosenEndpoint == "" {
		return
	}
	store.Acquire(now, stickyRouteLeaseTTL, key, baseProvider, chosenEndpoint, decision.Model)
	decision.Sticky.Assignment = "acquired"
	decision.Sticky.ServerInstance = chosenEndpoint
	if decision.Sticky.Reason == "" {
		decision.Sticky.Reason = "new sticky lease acquired"
	}
}

func stickyLeaseCandidate(candidates []RouteCandidate, harness, provider, model, endpoint string) (RouteCandidate, bool) {
	for _, candidate := range candidates {
		if !candidate.Eligible || candidate.Harness != harness || candidate.Model != model {
			continue
		}
		baseProvider, candidateEndpoint, _ := splitEndpointProviderRef(candidate.Provider)
		if baseProvider == "" {
			baseProvider = candidate.Provider
		}
		if baseProvider != provider {
			continue
		}
		candidateInstance := candidate.ServerInstance
		if candidateEndpoint == "" {
			candidateEndpoint = candidate.Endpoint
		}
		if candidateInstance == "" {
			candidateInstance = candidateEndpoint
		}
		if candidateInstance == endpoint || candidateEndpoint == endpoint {
			return candidate, true
		}
	}
	return RouteCandidate{}, false
}

func stickyLeaseAnyEndpoint(candidates []RouteCandidate, harness, provider, endpoint string) (RouteCandidate, bool) {
	for _, candidate := range candidates {
		if candidate.Harness != harness {
			continue
		}
		baseProvider, candidateEndpoint, _ := splitEndpointProviderRef(candidate.Provider)
		if baseProvider == "" {
			baseProvider = candidate.Provider
		}
		if baseProvider != provider {
			continue
		}
		candidateInstance := candidate.ServerInstance
		if candidateEndpoint == "" {
			candidateEndpoint = candidate.Endpoint
		}
		if candidateInstance == "" {
			candidateInstance = candidateEndpoint
		}
		if candidateInstance == endpoint || candidateEndpoint == endpoint {
			return candidate, true
		}
	}
	return RouteCandidate{}, false
}

func (s *service) routeEndpointLoadsResolver(now time.Time) func(provider, endpoint, model string) (routing.EndpointLoad, bool) {
	if s == nil {
		return nil
	}
	leaseStore := s.routeLeaseStore()
	utilStore := s.routeUtilizationStore()
	return func(provider, endpoint, model string) (routing.EndpointLoad, bool) {
		leaseCounts := leaseStore.LeaseCounts(now, provider, model)
		loads := utilStore.EndpointLoads(provider, model, leaseCounts)
		load, ok := loads[endpoint]
		if !ok {
			if count, ok := leaseCounts[endpoint]; ok {
				return routing.EndpointLoad{
					LeaseCount:       count,
					NormalizedLoad:   float64(count),
					UtilizationFresh: false,
				}, true
			}
			return routing.EndpointLoad{}, false
		}
		return routing.EndpointLoad{
			LeaseCount:           load.LeaseCount,
			NormalizedLoad:       load.NormalizedLoad,
			UtilizationFresh:     load.UtilizationFresh,
			UtilizationSaturated: load.UtilizationSaturated,
		}, true
	}
}

package routehealth

import (
	"sort"
	"strings"
	"sync"
	"time"
)

// DefaultLeaseTTL bounds how long an in-process sticky route lease may live
// without being refreshed.
const DefaultLeaseTTL = 5 * time.Minute

// LeaseKey identifies one sticky lease scope.
type LeaseKey struct {
	StickyKey string
	Provider  string
	Model     string
}

// Lease describes one sticky endpoint assignment.
type Lease struct {
	Key         LeaseKey
	Provider    string
	Endpoint    string
	Model       string
	AcquiredAt  time.Time
	RefreshedAt time.Time
	ExpiresAt   time.Time
}

// LeaseInvalidation records why a lease was removed.
type LeaseInvalidation struct {
	Key        LeaseKey
	Provider   string
	Endpoint   string
	Model      string
	Reason     string
	RecordedAt time.Time
}

// LeaseStore owns in-process sticky route assignments. It is safe for
// concurrent use.
type LeaseStore struct {
	mu            sync.Mutex
	leases        map[LeaseKey]Lease
	invalidations map[LeaseKey]LeaseInvalidation
}

// NewLeaseStore returns an empty lease store.
func NewLeaseStore() *LeaseStore {
	return &LeaseStore{
		leases:        make(map[LeaseKey]Lease),
		invalidations: make(map[LeaseKey]LeaseInvalidation),
	}
}

// NormalizeLeaseKey trims whitespace from the lease dimensions.
func NormalizeLeaseKey(stickyKey, provider, model string) LeaseKey {
	return LeaseKey{
		StickyKey: strings.TrimSpace(stickyKey),
		Provider:  strings.TrimSpace(provider),
		Model:     strings.TrimSpace(model),
	}
}

// Live returns the current lease for key when it has not expired.
func (s *LeaseStore) Live(now time.Time, key LeaseKey) (Lease, bool) {
	if s == nil {
		return Lease{}, false
	}
	now = normalizeLeaseNow(now)

	s.mu.Lock()
	defer s.mu.Unlock()
	s.expireLocked(now)
	lease, ok := s.leases[key]
	if !ok {
		return Lease{}, false
	}
	return lease, true
}

// Acquire stores or refreshes a lease for key.
func (s *LeaseStore) Acquire(now time.Time, ttl time.Duration, key LeaseKey, provider, endpoint, model string) Lease {
	if s == nil {
		return Lease{}
	}
	now = normalizeLeaseNow(now)
	if ttl <= 0 {
		ttl = DefaultLeaseTTL
	}
	key = NormalizeLeaseKey(key.StickyKey, key.Provider, key.Model)
	provider = strings.TrimSpace(provider)
	endpoint = strings.TrimSpace(endpoint)
	model = strings.TrimSpace(model)

	s.mu.Lock()
	defer s.mu.Unlock()
	s.expireLocked(now)

	lease := Lease{
		Key:         key,
		Provider:    provider,
		Endpoint:    endpoint,
		Model:       model,
		AcquiredAt:  now,
		RefreshedAt: now,
		ExpiresAt:   now.Add(ttl),
	}
	if existing, ok := s.leases[key]; ok {
		if existing.Provider == provider && existing.Endpoint == endpoint && existing.Model == model {
			lease.AcquiredAt = existing.AcquiredAt
		}
	}
	s.leases[key] = lease
	delete(s.invalidations, key)
	return lease
}

// Invalidate removes the lease for key and records the reason.
func (s *LeaseStore) Invalidate(now time.Time, key LeaseKey, reason string) (LeaseInvalidation, bool) {
	if s == nil {
		return LeaseInvalidation{}, false
	}
	now = normalizeLeaseNow(now)
	key = NormalizeLeaseKey(key.StickyKey, key.Provider, key.Model)

	s.mu.Lock()
	defer s.mu.Unlock()
	s.expireLocked(now)
	lease, ok := s.leases[key]
	if !ok {
		return LeaseInvalidation{}, false
	}
	delete(s.leases, key)
	invalidation := LeaseInvalidation{
		Key:        key,
		Provider:   lease.Provider,
		Endpoint:   lease.Endpoint,
		Model:      lease.Model,
		Reason:     strings.TrimSpace(reason),
		RecordedAt: now,
	}
	s.invalidations[key] = invalidation
	return invalidation, true
}

// InvalidateEndpoint removes every lease for the provider/model scope that
// points at the named endpoint and records the supplied reason.
func (s *LeaseStore) InvalidateEndpoint(now time.Time, provider, endpoint, model, reason string) []LeaseInvalidation {
	if s == nil {
		return nil
	}
	now = normalizeLeaseNow(now)
	provider = strings.TrimSpace(provider)
	endpoint = strings.TrimSpace(endpoint)
	model = strings.TrimSpace(model)

	s.mu.Lock()
	defer s.mu.Unlock()
	s.expireLocked(now)
	if len(s.leases) == 0 {
		return nil
	}
	var out []LeaseInvalidation
	for key, lease := range s.leases {
		if provider != "" && lease.Provider != provider {
			continue
		}
		if endpoint != "" && lease.Endpoint != endpoint {
			continue
		}
		if model != "" && lease.Model != model {
			continue
		}
		delete(s.leases, key)
		invalidation := LeaseInvalidation{
			Key:        key,
			Provider:   lease.Provider,
			Endpoint:   lease.Endpoint,
			Model:      lease.Model,
			Reason:     strings.TrimSpace(reason),
			RecordedAt: now,
		}
		s.invalidations[key] = invalidation
		out = append(out, invalidation)
	}
	return out
}

// LiveByScope returns the live leases for provider/model, ordered by sticky
// key for deterministic tests.
func (s *LeaseStore) LiveByScope(now time.Time, provider, model string) []Lease {
	if s == nil {
		return nil
	}
	now = normalizeLeaseNow(now)
	provider = strings.TrimSpace(provider)
	model = strings.TrimSpace(model)

	s.mu.Lock()
	defer s.mu.Unlock()
	s.expireLocked(now)
	if len(s.leases) == 0 {
		return nil
	}
	out := make([]Lease, 0, len(s.leases))
	for _, lease := range s.leases {
		if provider != "" && lease.Provider != provider {
			continue
		}
		if model != "" && lease.Model != model {
			continue
		}
		out = append(out, lease)
	}
	sort.Slice(out, func(i, j int) bool {
		if out[i].Endpoint != out[j].Endpoint {
			return out[i].Endpoint < out[j].Endpoint
		}
		return out[i].Key.StickyKey < out[j].Key.StickyKey
	})
	return out
}

// LeaseCounts returns the live lease count per endpoint for provider/model.
func (s *LeaseStore) LeaseCounts(now time.Time, provider, model string) map[string]int {
	leases := s.LiveByScope(now, provider, model)
	if len(leases) == 0 {
		return nil
	}
	counts := make(map[string]int, len(leases))
	for _, lease := range leases {
		counts[lease.Endpoint]++
	}
	return counts
}

// LastInvalidation returns the most recent invalidation recorded for key.
func (s *LeaseStore) LastInvalidation(key LeaseKey) (LeaseInvalidation, bool) {
	if s == nil {
		return LeaseInvalidation{}, false
	}
	key = NormalizeLeaseKey(key.StickyKey, key.Provider, key.Model)

	s.mu.Lock()
	defer s.mu.Unlock()
	invalidation, ok := s.invalidations[key]
	return invalidation, ok
}

