func routingDecisionEventCandidates(in []RouteCandidate) []ServiceRoutingDecisionCandidate {
	if len(in) == 0 {
		return nil
	}
	out := make([]ServiceRoutingDecisionCandidate, len(in))
	for i, c := range in {
		out[i] = ServiceRoutingDecisionCandidate{
			Harness:            c.Harness,
			Provider:           c.Provider,
			Endpoint:           c.Endpoint,
			ServerInstance:     c.ServerInstance,
			Model:              c.Model,
			Score:              c.Score,
			CostUSDPer1kTokens: c.CostUSDPer1kTokens,
			CostSource:         c.CostSource,
			Eligible:           c.Eligible,
			Reason:             c.Reason,
			FilterReason:       c.FilterReason,
			Components: ServiceRoutingDecisionComponents{
				Power:            c.Components.Power,
				Cost:             c.Components.Cost,
				CostClass:        c.Components.CostClass,
				LatencyMS:        c.Components.LatencyMS,
				SpeedTPS:         c.Components.SpeedTPS,
				SuccessRate:      c.Components.SuccessRate,
				QuotaOK:          c.Components.QuotaOK,
				QuotaPercentUsed: c.Components.QuotaPercentUsed,
				QuotaTrend:       c.Components.QuotaTrend,
				Capability:       c.Components.Capability,
			},
			Utilization: ServiceRoutingUtilizationState{
				Source:         c.Utilization.Source,
				Freshness:      c.Utilization.Freshness,
				ActiveRequests: c.Utilization.ActiveRequests,
				QueuedRequests: c.Utilization.QueuedRequests,
				MaxConcurrency: c.Utilization.MaxConcurrency,
				CachePressure:  c.Utilization.CachePressure,
				ObservedAt:     c.Utilization.ObservedAt,
			},
		}
	}
	return out
}

type ServiceRoutingDecisionData struct {
	Harness          string                         `json:"harness"`
	Provider         string                         `json:"provider,omitempty"`
	Endpoint         string                         `json:"endpoint,omitempty"`
	ServerInstance   string                         `json:"server_instance,omitempty"`
	Model            string                         `json:"model"`
	Reason           string                         `json:"reason"`
	Sticky           ServiceRoutingStickyState      `json:"sticky,omitempty"`
	Utilization      ServiceRoutingUtilizationState `json:"utilization,omitempty"`
	RequestedHarness string                         `json:"requested_harness,omitempty"`
	HarnessSource    string                         `json:"harness_source,omitempty"`
	FallbackChain    []string                       `json:"fallback_chain,omitempty"`
	SessionID        string                         `json:"session_id,omitempty"`

	// Candidates exposes the full ranked decision trace. Each candidate
	// carries per-axis component scores (cost / latency / success rate /
	// capability) plus an explicit filter_reason for rejected entries.
	Candidates []ServiceRoutingDecisionCandidate `json:"candidates,omitempty"`
}

// ServiceRoutingDecisionCandidate is one entry in the routing-decision
// event's candidates list. Mirrors RouteCandidate but with JSON tags
// suited for event consumers.
type ServiceRoutingDecisionCandidate struct {
	Harness            string                           `json:"harness"`
	Provider           string                           `json:"provider,omitempty"`
	Endpoint           string                           `json:"endpoint,omitempty"`
	ServerInstance     string                           `json:"server_instance,omitempty"`
	Model              string                           `json:"model,omitempty"`
	Score              float64                          `json:"score"`
	CostUSDPer1kTokens float64                          `json:"cost_usd_per_1k_tokens,omitempty"`
	CostSource         string                           `json:"cost_source,omitempty"`
	Eligible           bool                             `json:"eligible"`
	Reason             string                           `json:"reason,omitempty"`
	FilterReason       string                           `json:"filter_reason,omitempty"`

		// TestOnly harnesses (script/virtual) only reachable via explicit override.
		if h.TestOnly && canonicalHarness != h.Name {
			continue
		}
		// Automatic profile/tier routing is restricted to harnesses with full
		// coverage. Explicit Harness pins can still use experimental/ad-hoc
		// harnesses.
		if canonicalHarness == "" && !h.AutoRoutingEligible {
			continue
		}
		// Hard harness override: skip non-matching harnesses.
		if canonicalHarness != "" && canonicalHarness != h.Name {
			continue
		}
		entries := buildHarnessCandidates(h, req, in)
		ranked = append(ranked, entries...)
	}

	// Compute scores only after eligibility is final. Rejected candidates keep
	// a zero score because cost/utilization/performance/sticky ranking should
	// never influence the eligibility boundary.
	for i := range ranked {
		if !ranked[i].out.Eligible {
			continue
		}
		ranked[i].out.Score = scorePolicy(req.Profile, ranked[i].internal)
		ranked[i].out.Reason = fmt.Sprintf("profile=%s; score=%.1f", req.Profile, ranked[i].out.Score)
	}
	neutralCost, hasKnownCost := neutralKnownCost(ranked)

	// Sort: eligible first, then descending score, then cost, then locality,
	// then alphabetical.
	sort.SliceStable(ranked, func(i, j int) bool {
		ei, ej := ranked[i].out.Eligible, ranked[j].out.Eligible
		if ei != ej {
			return ei
		}
		if !ei {
			return ranked[i].out.Harness < ranked[j].out.Harness
		}
		if ranked[i].out.Score != ranked[j].out.Score {
			return ranked[i].out.Score > ranked[j].out.Score
		}
		if hasKnownCost {
			ci := candidateCostTieValue(ranked[i], neutralCost)
			cj := candidateCostTieValue(ranked[j], neutralCost)
			if ci != cj {
				return ci < cj
			}
		}
		// Locality tiebreak: prefer local cost-class.
		li := costClassRank[ranked[i].internal.CostClass] == 0
		lj := costClassRank[ranked[j].internal.CostClass] == 0
		if li != lj {
			return li
		}
		if sameLocalEndpointGroup(ranked[i].internal, ranked[j].internal) {
			if ranked[i].internal.EndpointSaturated != ranked[j].internal.EndpointSaturated {
				return !ranked[i].internal.EndpointSaturated
			}
			if ranked[i].internal.EndpointLoad != ranked[j].internal.EndpointLoad {
				return ranked[i].internal.EndpointLoad < ranked[j].internal.EndpointLoad
			}
		}
		if ranked[i].out.Harness != ranked[j].out.Harness {
			return ranked[i].out.Harness < ranked[j].out.Harness
		}
		return ranked[i].out.Provider < ranked[j].out.Provider
	})

	out := make([]Candidate, len(ranked))
	for i := range ranked {
		out[i] = ranked[i].out
	}

	if err := explicitPinError(req, in); err != nil {
		return &Decision{Candidates: out}, err
	}

	for i := range out {
		if out[i].Eligible {
			return &Decision{
				Harness:        out[i].Harness,
				Provider:       out[i].Provider,
				Endpoint:       out[i].Endpoint,
				ServerInstance: out[i].ServerInstance,
				Model:          out[i].Model,
				Reason:         fmt.Sprintf("profile=%s; score=%.1f", req.Profile, out[i].Score),
				Candidates:     out,
			}, nil
		}
	}
	if quotaErr := allProvidersQuotaExhaustedError(ranked); quotaErr != nil {
		return &Decision{Candidates: out}, quotaErr
	}
	if requested := requestedModelIntent(req); requested != "" && req.Provider == "" && canonicalHarness == "" && hasLiveDiscoveryCandidates(ranked) {
		return &Decision{Candidates: out}, fmt.Errorf("no live endpoint offers a match for %s", requested)
	}
	if missingCapability := missingProfileCapability(req); missingCapability != "" {
		return &Decision{Candidates: out}, &ErrNoProfileCandidate{
			Profile:           req.Profile,
			MissingCapability: missingCapability,
			Rejected:          len(out),
		}
	}
	return &Decision{Candidates: out}, noViableCandidateError(req, len(out))
}

// allProvidersQuotaExhaustedError returns ErrAllProvidersQuotaExhausted when
// at least one routing candidate was rejected solely because its provider is
// in the quota_exhausted state and no other candidate was eligible. The set
// of otherwise-eligible candidates collapses to those flagged with
// quotaExhaustedRetryAfter (the engine sets this only when the candidate
// passed every other gate). When that set is empty the existing
// no-viable / no-profile-candidate / live-discovery errors describe the
// failure more precisely.
func allProvidersQuotaExhaustedError(ranked []rankedCandidate) error {
	var exhausted []string
	seen := make(map[string]struct{})
	var earliest time.Time
	for _, c := range ranked {
		if c.quotaExhaustedRetryAfter.IsZero() {
			continue
		}
		name := c.out.Provider
		if name == "" {
			name = c.out.Harness
		}
		if _, dup := seen[name]; !dup {
			seen[name] = struct{}{}
			exhausted = append(exhausted, name)
		}
		if earliest.IsZero() || c.quotaExhaustedRetryAfter.Before(earliest) {
			earliest = c.quotaExhaustedRetryAfter
		}
	}
	if len(exhausted) == 0 {
		return nil
	}
	return &ErrAllProvidersQuotaExhausted{
		RetryAfter:         earliest,
		ExhaustedProviders: exhausted,
	}
}

func noViableCandidateError(req Request, rejected int) *NoViableCandidateError {
	return &NoViableCandidateError{
		Rejected: rejected,
		Model:    req.Model,
		Provider: req.Provider,
		Harness:  canonicalHarnessPin(req.Harness),
		MinPower: req.MinPower,
		MaxPower: req.MaxPower,
	}
}

func explicitPinError(req Request, in Inputs) error {
	canonicalHarness := canonicalHarnessPin(req.Harness)
	if req.Profile != "" && (canonicalHarness != "" || req.Model != "") {
		if constraint, ok := explicitProfileConstraint(req.Profile, req.ProviderPreference); ok {
			if canonicalHarness != "" {
				if h, ok := findHarness(in.Harnesses, canonicalHarness); ok && harnessViolatesProfileConstraint(h, constraint) {
					return &ErrProfilePinConflict{
						Profile:           req.Profile,
						ConflictingPin:    "Harness=" + canonicalHarness,
						ProfileConstraint: constraint,
					}
				}
			}
			if req.Model != "" && modelPinViolatesProfileConstraint(req.Model, in, constraint) {
				return &ErrProfilePinConflict{
					Profile:           req.Profile,
					ConflictingPin:    "Model=" + req.Model,
					ProfileConstraint: constraint,
				}
			}
		}
	}

	if canonicalHarness == "" || req.Model == "" {
		return nil
	}
	// Pi can route any provider-pinned model (lmstudio, omlx, openrouter,
	// etc.); the pi CLI owns concrete model validation in that case.
	// Mirrors the bypass in service_execute.go validateExplicitHarnessModel.
	if canonicalHarness == "pi" && req.Provider != "" {
		return nil
	}
	h, ok := findHarness(in.Harnesses, canonicalHarness)
	if !ok || h.SupportedModels == nil || harnessSupportsModel(h.SupportedModels, req.Model) {
		return nil
	}
	return &ErrHarnessModelIncompatible{
		Harness:         canonicalHarness,
		Model:           req.Model,
		SupportedModels: append([]string(nil), h.SupportedModels...),
	}
}

func canonicalHarnessPin(harness string) string {
	if harness == "local" {
		return "fiz"
	}
	return harness
}

func findHarness(harnesses []HarnessEntry, name string) (HarnessEntry, bool) {
	for _, h := range harnesses {
		if h.Name == name {
			return h, true
		}
	}
	return HarnessEntry{}, false
}

func harnessSupportsModel(supported []string, model string) bool {
	for _, candidate := range supported {
		if candidate == model {
			return true
		}
	}
	return false
}

func explicitProfileConstraint(profile, providerPreference string) (string, bool) {
	switch providerPreference {
	case ProviderPreferenceLocalOnly:
		return ProviderPreferenceLocalOnly, true
	case ProviderPreferenceSubscriptionOnly:
		return ProviderPreferenceSubscriptionOnly, true
	}
	switch profile {
	case "local", "offline", "air-gapped":
		return ProviderPreferenceLocalOnly, true
	case "smart", "code-smart":
		return ProviderPreferenceSubscriptionOnly, true
	default:
		return "", false
	}
}

func harnessViolatesProfileConstraint(h HarnessEntry, constraint string) bool {
	switch constraint {
	case ProviderPreferenceLocalOnly:
		return !h.IsLocal
	case ProviderPreferenceSubscriptionOnly:
		return !h.IsSubscription
	default:
		return false
	}
}

func modelPinViolatesProfileConstraint(model string, in Inputs, constraint string) bool {
	var constrainedCanServe bool
	var outsideCanServe bool
	for _, h := range in.Harnesses {
		if h.TestOnly || !h.AutoRoutingEligible {
			continue
		}
		if !harnessCanServeExactModel(h, model) {
			continue
		}
		if harnessViolatesProfileConstraint(h, constraint) {
			outsideCanServe = true
		} else {
			constrainedCanServe = true
		}
	}
	return !constrainedCanServe && outsideCanServe
}

func harnessCanServeExactModel(h HarnessEntry, model string) bool {
	if len(h.SupportedModels) > 0 && harnessSupportsModel(h.SupportedModels, model) {
		return true
	}
	if h.DefaultModel == model {
		return true
	}
	providers := h.Providers
	if len(providers) == 0 {
		providers = []ProviderEntry{{Name: ""}}
	}
	for _, p := range providers {
		if p.DefaultModel == model {
			return true
		}
		if len(p.DiscoveredIDs) > 0 && FuzzyMatch(model, p.DiscoveredIDs) != "" {
			return true
		}
	}
	return false
}

